/**
 * Development seed — real English pyramid, 2026-27 season.
 *
 * Leagues, clubs and first-team squads come from prisma/data/football-2026-27.json, generated by
 * scripts/import_wikipedia.py (Wikipedia, CC BY-SA 4.0). Players are marked rightsStatus=PENDING:
 * names/likeness and club marks still need licensing before any commercial use (spec §10).
 * No crests are included — clubs show a generated badge in their colours until licensed crest
 * assets are supplied (Club.crestUrl).
 *
 * Match data is SIMULATED (DEV provider). The seed plays three historical gameweeks so form,
 * results and MP value history exist, then opens the next gameweek for entries.
 */
import "dotenv/config";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { Position } from "../src/generated/prisma/client";
import { FOOTBALL_PACKS } from "../src/config/packs";
import { MAX_SUPPLY, tierFor } from "../src/config/tiers";
import { seededRandom } from "../src/domain/random";
import { hashPassword } from "../src/server/auth/password";
import { db } from "../src/server/db";
import { createGameweek, finaliseGameweek, simulateFixturesNow } from "../src/server/gameweeks";
import { executeRelease, scheduleRelease } from "../src/server/supply";
import { revalueAll } from "../src/server/valuation";

interface DataPlayer {
  name: string;
  position: Position;
  nationality: string;
  squadNumber: number | null;
  onLoan: boolean;
}
interface DataClub {
  article: string;
  name: string;
  short: string;
  primaryColour: string;
  secondaryColour: string;
  kit: Record<string, unknown>;
  revision: string;
  players: DataPlayer[];
}
interface DataLeague {
  code: string;
  name: string;
  tier: number;
  isTopFlight: boolean;
  clubs: DataClub[];
}

const DAY = 24 * 3600_000;
const HISTORY_GAMEWEEKS = 3;
const rng = seededRandom(20261109);

function splitName(full: string) {
  const parts = full.trim().split(/\s+/);
  if (parts.length === 1) return { firstName: "", lastName: parts[0] };
  return { firstName: parts[0], lastName: parts.slice(1).join(" ") };
}

function displayName(full: string) {
  if (full.length <= 18) return full;
  const { firstName, lastName } = splitName(full);
  return firstName ? `${firstName[0]}. ${lastName}` : lastName;
}

async function main() {
  if (await db.sport.findUnique({ where: { code: "football" } })) {
    console.log("Database already seeded — truncate it (or run `npm run db:reset`) for a fresh start.");
    return;
  }
  const data = JSON.parse(readFileSync(join(__dirname, "data", "football-2026-27.json"), "utf8")) as { season: string; leagues: DataLeague[] };
  const sport = await db.sport.create({ data: { code: "football", name: "Football" } });
  for (const p of FOOTBALL_PACKS) {
    await db.packSku.create({
      data: { sportId: sport.id, code: p.code, version: p.version, name: p.name, kind: p.kind, priceMinor: p.priceMinor, config: p.config },
    });
  }

  // A player loaned in appears on both clubs' pages; keep them only at the club they play for.
  const loanedIn = new Set<string>();
  for (const l of data.leagues) for (const c of l.clubs) for (const p of c.players) if (p.onLoan) loanedIn.add(`${p.name}|${p.position}`);

  let seq = 0;
  const templatesByClub = new Map<string, Array<{ id: string; category: string; position: Position }>>();
  for (const lg of data.leagues) {
    const league = await db.league.create({
      data: { sportId: sport.id, code: lg.code, name: lg.name, country: "ENG", tier: lg.tier, isTopFlight: lg.isTopFlight },
    });
    for (const c of lg.clubs) {
      const club = await db.club.create({
        data: {
          leagueId: league.id,
          code: c.short,
          name: c.name,
          shortName: c.short,
          primaryColour: c.primaryColour,
          secondaryColour: c.secondaryColour,
          kit: c.kit as object,
          sourceRef: `wikipedia:${c.article}@${c.revision}`,
          simStrength: Math.round(100 - lg.tier * 12 + rng.int(20)),
        },
      });
      const list: Array<{ id: string; category: string; position: Position }> = [];
      for (const p of c.players) {
        if (!p.onLoan && loanedIn.has(`${p.name}|${p.position}`)) continue;
        seq++;
        const { firstName, lastName } = splitName(p.name);
        const player = await db.player.create({
          data: {
            sportId: sport.id,
            clubId: club.id,
            firstName,
            lastName,
            displayName: displayName(p.name),
            position: p.position,
            squadNumber: p.squadNumber,
            nationality: p.nationality,
            rightsStatus: "PENDING",
            providerRefs: { sim: `sim-pl-${seq}` },
          },
        });
        const category = tierFor(lg.tier, p.squadNumber);
        const tpl = await db.cardTemplate.create({ data: { playerId: player.id, category, maxSupply: MAX_SUPPLY[category] } });
        list.push({ id: tpl.id, category, position: p.position });
      }
      templatesByClub.set(c.short, list);
    }
    console.log(`${lg.name}: ${lg.clubs.length} clubs`);
  }
  console.log(`Created ${seq} players`);

  // Collection sets — examples; every completed set awards 10 MP credit (≈ £10).
  const sets: Array<{ code: string; name: string; description: string; templateIds: string[] }> = [];
  for (const short of ["ARS", "LIV", "MCI", "MUN", "CHE", "TOT"]) {
    const golds = (templatesByClub.get(short) ?? []).filter((t) => t.category === "GOLD").slice(0, 4);
    const club = await db.club.findUniqueOrThrow({ where: { code: short } });
    if (golds.length >= 3) sets.push({ code: `golds-${short.toLowerCase()}`, name: `${club.name} Golds`, description: `Collect ${golds.length} Gold ${club.name} players.`, templateIds: golds.map((t) => t.id) });
  }
  for (const short of ["WRE", "WHU"]) {
    const silvers = (templatesByClub.get(short) ?? []).filter((t) => t.category === "SILVER").slice(0, 4);
    const club = await db.club.findUnique({ where: { code: short } });
    if (club && silvers.length >= 3) sets.push({ code: `silvers-${short.toLowerCase()}`, name: `${club.name} Silvers`, description: `Collect ${silvers.length} Silver ${club.name} players.`, templateIds: silvers.map((t) => t.id) });
  }
  const nlClubs = data.leagues.find((l) => l.code === "NL")!.clubs.map((c) => c.short);
  const nlKeepers = nlClubs.flatMap((s) => (templatesByClub.get(s) ?? []).filter((t) => t.position === "GK").slice(0, 1)).slice(0, 5);
  sets.push({ code: "national-league-keepers", name: "National League No. 1s", description: "Five National League goalkeepers.", templateIds: nlKeepers.map((t) => t.id) });
  for (const s of sets) {
    await db.collectionSet.create({
      data: { sportId: sport.id, code: s.code, name: s.name, description: s.description, reward: { mpCreditMinor: 1000 }, requirements: { create: s.templateIds.map((templateId) => ({ templateId })) } },
    });
  }
  console.log(`Created ${sets.length} collection sets`);

  // First weekly release (the next is auto-scheduled a week later).
  const now = Date.now();
  const release = await scheduleRelease(sport.id, new Date(now - 28 * DAY), { perTemplate: { BRONZE: 4, SILVER: 4, GOLD: 3 }, overrides: {} }, null);
  const r = await executeRelease(release.id, null);
  console.log(`Initial supply release minted ${r.minted} cards`, r.byCategory ?? "");
  await revalueAll(new Date(now - 28 * DAY));

  const adminEmail = (process.env.SEED_ADMIN_EMAIL ?? "admin@collectr.dev").toLowerCase();
  await db.user.create({
    data: {
      email: adminEmail,
      displayName: "Admin",
      passwordHash: await hashPassword(process.env.SEED_ADMIN_PASSWORD ?? "collectr-admin"),
      role: "ADMIN",
      emailVerifiedAt: new Date(),
    },
  });
  console.log(`Admin account: ${adminEmail}`);

  // Simulated history so form, results and value trends exist.
  for (let n = 1; n <= HISTORY_GAMEWEEKS; n++) {
    const locksAt = new Date(now - (HISTORY_GAMEWEEKS + 1 - n) * 7 * DAY);
    const gw = await createGameweek({ season: data.season, number: n, opensAt: new Date(locksAt.getTime() - 3 * DAY), firstKickoffAt: locksAt, actorId: null });
    await simulateFixturesNow(gw.id, "all", null);
    await finaliseGameweek(gw.id, null, new Date(locksAt.getTime() + 3 * DAY));
    console.log(`Gameweek ${n} simulated and settled`);
  }
  const gw = await createGameweek({ season: data.season, number: HISTORY_GAMEWEEKS + 1, opensAt: new Date(now), firstKickoffAt: new Date(now + 3 * DAY), actorId: null });
  console.log(`Gameweek ${gw.number} open for entries`);
}

main()
  .then(() => db.$disconnect())
  .catch(async (e) => {
    console.error(e);
    await db.$disconnect();
    process.exit(1);
  });
